import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DqVSm8kp.js";const m=JSON.parse('{"title":"Parametres","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/settings.md","filePath":"fr/guide/settings.md"}'),s={name:"fr/guide/settings.md"};function l(n,e,i,u,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="parametres" tabindex="-1">Parametres <a class="header-anchor" href="#parametres" aria-label="Permalink to &quot;Parametres&quot;">​</a></h1><p>La page Parametres vous permet de configurer votre connexion Ollama, les parametres par defaut des modeles et les preferences de l&#39;application.</p><p><strong>Element de la barre laterale :</strong> Parametres <strong>Route :</strong> <code>/settings</code></p><h2 id="connexion" tabindex="-1">Connexion <a class="header-anchor" href="#connexion" aria-label="Permalink to &quot;Connexion&quot;">​</a></h2><h3 id="url-ollama" tabindex="-1">URL Ollama <a class="header-anchor" href="#url-ollama" aria-label="Permalink to &quot;URL Ollama&quot;">​</a></h3><p>Definissez l&#39;URL ou Ollama est en cours d&#39;execution. Par defaut : <code>http://localhost:11434</code>.</p><h3 id="test-de-connexion" tabindex="-1">Test de connexion <a class="header-anchor" href="#test-de-connexion" aria-label="Permalink to &quot;Test de connexion&quot;">​</a></h3><p>Cliquez sur <strong>Tester la connexion</strong> pour verifier que LLMxRay peut atteindre Ollama. Le resultat affiche :</p><ul><li><strong>Connecte</strong> (vert) -- Ollama est accessible et repond</li><li><strong>Deconnecte</strong> (rouge) -- Verifiez que <code>ollama serve</code> est en cours d&#39;execution</li></ul><div class="tip custom-block"><p class="custom-block-title">Ollama distant</p><p>Si Ollama tourne sur une autre machine, saisissez son adresse IP et son port (par ex., <code>http://192.168.1.100:11434</code>). Assurez-vous que le proxy Vite est mis a jour dans <code>vite.config.ts</code> ou que le CORS est configure sur l&#39;instance Ollama distante.</p></div><h2 id="parametres-par-defaut" tabindex="-1">Parametres par defaut <a class="header-anchor" href="#parametres-par-defaut" aria-label="Permalink to &quot;Parametres par defaut&quot;">​</a></h2><h3 id="temperature" tabindex="-1">Temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;Temperature&quot;">​</a></h3><p>Controle l&#39;aleatoire dans les sorties du modele. Affichee avec une <strong>echelle visuelle</strong> et une <strong>infobulle pedagogique</strong> :</p><table tabindex="0"><thead><tr><th>Valeur</th><th>Effet</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>Deterministe -- choisit toujours le token le plus probable</td></tr><tr><td><strong>0.7</strong></td><td>Equilibre -- valeur par defaut pour la plupart des cas d&#39;utilisation</td></tr><tr><td><strong>1.0+</strong></td><td>Creatif -- sortie plus variee, parfois surprenante</td></tr></tbody></table><h3 id="longueur-de-contexte" tabindex="-1">Longueur de contexte <a class="header-anchor" href="#longueur-de-contexte" aria-label="Permalink to &quot;Longueur de contexte&quot;">​</a></h3><p>Definit le nombre maximal de tokens que le modele prend en compte. Des valeurs plus elevees permettent des conversations plus longues mais consomment plus de memoire.</p><p>Les deux parametres incluent des echelles visuelles et des explications en langage courant de ce que fait chaque reglage.</p><h2 id="catalogue-de-modeles" tabindex="-1">Catalogue de modeles <a class="header-anchor" href="#catalogue-de-modeles" aria-label="Permalink to &quot;Catalogue de modeles&quot;">​</a></h2><p>L&#39;onglet Modeles (egalement accessible comme element de la barre laterale) fournit :</p><ul><li>Un catalogue consultable des modeles installes</li><li>Des badges de detection des capacites (raisonnement, vision, embedding, appel d&#39;outils)</li><li>Details d&#39;architecture et nombre de parametres</li><li>Fonctionnalites de comparaison pour evaluer les modeles cote a cote</li></ul><p>Consultez le chapitre <a href="./models.html">Modeles</a> pour tous les details.</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>Basculez entre :</p><ul><li><strong>Mode sombre</strong> -- Par defaut, optimise pour une utilisation prolongee</li><li><strong>Mode clair</strong> -- Alternative a haut contraste</li><li><strong>Systeme</strong> -- Suit la preference de votre OS</li></ul><p>Le bouton de theme est egalement disponible dans la barre d&#39;en-tete.</p><h2 id="google-oauth2" tabindex="-1">Google OAuth2 <a class="header-anchor" href="#google-oauth2" aria-label="Permalink to &quot;Google OAuth2&quot;">​</a></h2><p>Pour les modeles de l&#39;Atelier d&#39;Outils qui interagissent avec les services Google (Calendar, Gmail), vous pouvez configurer OAuth2 :</p><ol><li>Saisissez votre <strong>Client ID</strong> depuis la Google Cloud Console</li><li>Cliquez sur <strong>Connecter</strong> pour autoriser l&#39;acces</li><li>Une fois connecte, les outils utilisant Google peuvent acceder a votre compte</li></ol><div class="warning custom-block"><p class="custom-block-title">Confidentialite</p><p>Les tokens OAuth sont stockes localement dans votre navigateur. LLMxRay n&#39;envoie jamais vos identifiants a un serveur externe.</p></div><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Commencez avec les valeurs par defaut</strong> -- La temperature par defaut (0.7) et la longueur de contexte fonctionnent bien pour la plupart des modeles.</li><li><strong>Reduisez la longueur de contexte</strong> si vous manquez de RAM/VRAM.</li><li>Le testeur de connexion est le moyen le plus rapide de diagnostiquer les problemes de type &quot;aucun modele&quot;.</li></ul>',31)])])}const h=t(s,[["render",l]]);export{m as __pageData,h as default};
